class Solution {
  public int sumOfPower(int[] nums, int k) {
    final int MOD = 1_000_000_007;
    long[][] dp = new long[k + 1][nums.length + 1];
    dp[0][0] = 1;
    for (int value : nums) {
      for (int sum = k; sum >= 0; sum--) {
        for (int count = nums.length - 1; count >= 0; count--) {
          if (sum + value <= k) {
            dp[sum + value][count + 1] = (dp[sum + value][count + 1] + dp[sum][count]) % MOD;
          }
        }
      }
    }
    long answer = 0, multiplier = 1;
    for (int count = nums.length; count >= 0; count--) {
      answer = (answer + dp[k][count] * multiplier) % MOD;
      multiplier = multiplier * 2 % MOD;
    }
    return (int) answer;
  }
}
